items = []; EV = {}
def pg(n): return B(f'EASA M04 SM01, p.1.{n-11} (PDF p.{n})', f'EASA M04 SM01, tr.1.{n-11} (PDF tr.{n})')
def mcq(tp, n, qen, qvi, ans, wrongs, xe, xv, rx, lvl=1):
    items.append(dict(kind='mcq', q=B(qen, qvi), opts=O([ans] + wrongs), correct=0, explain=B(xe, xv), level=lvl, topic=TT[tp], src=pg(n), origin='bo_sung', fixed_order=False, check='EASA text')); EV[qen] = dict(page=n, rx=rx)
def tf(tp, n, en, vi, v, xe, xv, rx, lvl=1):
    items.append(dict(kind='tf', q=B(en, vi), opts=[B('True', 'Đúng'), B('False', 'Sai')], correct=0 if v else 1, explain=B(xe, xv), level=lvl, topic=TT[tp], src=pg(n), origin='bo_sung', fixed_order=True, check='EASA text')); EV[en] = dict(page=n, rx=rx)
Y = lambda a, b=None: (a, b if b is not None else a)
mcq('cas',49,'The maximum voltage gain from a single transistor amplifier stage is usually between','Độ lợi điện áp cực đại từ một tầng khuếch đại dùng một transistor thường nằm trong khoảng',Y('10 and 100','10 và 100'),[Y('1 and 2','1 và 2'),Y('1 000 and 10 000','1 000 và 10 000'),Y('0.1 and 0.9','0,1 và 0,9')],'Hence two or three stages are cascaded for more gain.','Vì vậy nối tầng hai hoặc ba tầng để có thêm độ lợi.','between\\s+10\\s+and\\s+100')
mcq('cas',49,'Why are amplifiers connected in cascade?','Vì sao các bộ khuếch đại được nối tầng?',Y('Many applications need much more gain than one stage gives','Nhiều ứng dụng cần độ lợi lớn hơn nhiều so với một tầng'),[Y('A single stage cannot amplify at all','Một tầng không thể khuếch đại được'),Y('Cascading removes the need for a power supply','Nối tầng loại bỏ nhu cầu nguồn cấp'),Y('It lowers the gain to a safe value','Nó hạ độ lợi xuống mức an toàn')],'Each stage increases the voltage gain in succession.','Mỗi tầng nối tiếp làm tăng độ lợi điện áp.','much\\s+more\\s+amplification')
mcq('cas',50,'The total gain of a cascade is','Độ lợi tổng của chuỗi ghép tầng là',Y('the product of the gains of each stage','tích các độ lợi của từng tầng'),[Y('the sum of the stage gains','tổng các độ lợi từng tầng'),Y('the average of the stage gains','trung bình các độ lợi từng tầng'),Y('the gain of the first stage only','chỉ độ lợi của tầng đầu')],'In decibels the stage gains add.','Tính bằng dB thì độ lợi các tầng cộng lại.','product\\s+of\\s+the\\s+gains')
mcq('fb',50,'Feedback is','Hồi tiếp là',Y('sending a small portion of the output signal back to the input','đưa một phần nhỏ tín hiệu ra trở lại ngõ vào'),[Y('removing the input signal entirely','loại bỏ hoàn toàn tín hiệu vào'),Y('amplifying only the power supply ripple','chỉ khuếch đại gợn của nguồn'),Y('connecting two outputs together','nối hai ngõ ra với nhau')],'There are positive (regenerative) and negative (degenerative) feedback.','Có hồi tiếp dương (tái sinh) và âm (suy giảm).','small\\s+portion\\s+of\\s+the\\s+amplifier')
mcq('fb',50,'With positive feedback the returned signal is','Với hồi tiếp dương, tín hiệu trả về',Y('in phase with the input and adds constructively','cùng pha với tín hiệu vào và cộng cùng chiều'),[Y('out of phase and subtracts from the input','lệch pha và trừ vào tín hiệu vào'),Y('a dc level that shifts the Q-point only','mức một chiều chỉ làm dịch điểm Q'),Y('removed by the coupling capacitor','bị tụ ghép loại bỏ')],'The output amplitude is greater than without feedback.','Biên độ ra lớn hơn khi không có hồi tiếp.','in\\s+phase\\s+with\\s+the\\s+input')
mcq('fb',50,'Too much positive feedback causes','Hồi tiếp dương quá mức gây ra',Y('oscillation (e.g. an audio system squealing)','dao động (ví dụ hệ âm thanh hú)'),[Y('a lower output amplitude','biên độ ra thấp hơn'),Y('perfect stability of the Q-point','điểm Q ổn định hoàn hảo'),Y('a zero output','ngõ ra bằng không')],'Oscillators deliberately use positive feedback.','Mạch dao động cố ý dùng hồi tiếp dương.','Too\\s+much\\s+positive\\s+feedback',1)
mcq('fb',50,'Negative feedback signal is','Tín hiệu hồi tiếp âm',Y('out of phase with the input, giving a lower-amplitude output','lệch pha với tín hiệu vào, cho biên độ ra thấp hơn'),[Y('in phase with the input, raising the gain','cùng pha với tín hiệu vào, làm tăng độ lợi'),Y('always zero','luôn bằng không'),Y('identical to the supply voltage','giống điện áp nguồn')],'It causes destructive interference and degenerates the input signal.','Nó gây giao thoa triệt tiêu và làm suy giảm tín hiệu vào.','destructive\\s+interference')
mcq('fb',50,'Negative feedback tends to','Hồi tiếp âm có xu hướng',Y('stabilise the amplifier so it works in its normal range without oscillation','ổn định bộ khuếch đại để hoạt động trong dải bình thường không dao động'),[Y('make the amplifier oscillate','làm bộ khuếch đại dao động'),Y('double the gain of every stage','nhân đôi độ lợi mỗi tầng'),Y('remove the need for biasing','loại bỏ nhu cầu phân cực')],'It lowers gain but improves stability.','Nó giảm độ lợi nhưng tăng ổn định.','stabilize\\s+the\\s+amplifier')
mcq('fb',50,'The quiescent operating point (Q-point) is','Điểm làm việc tĩnh (điểm Q) là',Y('the steady-state voltage or current at a terminal with no input signal applied','điện áp hoặc dòng ở trạng thái ổn định tại một chân khi không có tín hiệu vào'),[Y('the highest output voltage the stage can deliver','điện áp ra cao nhất mà tầng có thể cấp'),Y('the frequency at which the gain is unity','tần số mà độ lợi bằng một'),Y('the point where the load line meets the signal','điểm đường tải gặp tín hiệu')],'An unstable Q-point drifts with temperature and supply.','Điểm Q không ổn định sẽ trôi theo nhiệt độ và nguồn.','steady-state\\s+voltage\\s+or\\s+current',2)
mcq('cpl',51,'Direct coupling is chosen for','Ghép trực tiếp được chọn cho',Y('pulse amplifiers, differential amplifiers and regulator circuits','mạch khuếch đại xung, vi sai và mạch ổn áp'),[Y('transformer impedance matching only','chỉ phối hợp trở kháng bằng biến áp'),Y('audio filters only','chỉ bộ lọc âm thanh'),Y('RF tuning circuits only','chỉ mạch chỉnh cộng hưởng RF')],'It uses fewer components and gives higher gain.','Nó dùng ít linh kiện hơn và cho độ lợi cao hơn.','pulse\\s+amplifiers,\\s+differential')
mcq('cpl',51,'An advantage of direct coupling is','Ưu điểm của ghép trực tiếp là',Y('good frequency response because no capacitors or inductors are used','đáp ứng tần số tốt vì không dùng tụ hay cuộn cảm'),[Y('perfect impedance matching between stages','phối hợp trở kháng hoàn hảo giữa các tầng'),Y('immunity to supply fluctuations','miễn nhiễm với dao động nguồn'),Y('isolation of each stage’s dc bias','cách ly phân cực một chiều từng tầng')],'Drawbacks: impedance matching and supply-voltage fluctuations.','Nhược điểm: phối hợp trở kháng và dao động nguồn.','good\\s+frequency\\s+response',2)
mcq('cpl',51,'RC coupling is the most common method because it','Ghép RC là phương pháp phổ biến nhất vì nó',Y('eliminates the impedance-matching problems of direct coupling','loại bỏ vấn đề phối hợp trở kháng của ghép trực tiếp'),[Y('amplifies dc signals best','khuếch đại tín hiệu một chiều tốt nhất'),Y('uses no capacitors','không dùng tụ điện'),Y('gives the largest possible gain','cho độ lợi lớn nhất có thể')],'The capacitor blocks the dc bias and passes the ac signal.','Tụ chặn phân cực một chiều và cho tín hiệu xoay chiều đi qua.','most\\s+common\\s+method\\s+of\\s+coupling')
mcq('cpl',51,'In RC coupling the coupling capacitor','Trong ghép RC, tụ ghép',Y('blocks the dc bias and passes the ac signal to the next stage','chặn phân cực một chiều và cho tín hiệu xoay chiều sang tầng sau'),[Y('passes dc and blocks ac','cho dc đi qua và chặn ac'),Y('stores the signal for later release','lưu tín hiệu để giải phóng sau'),Y('replaces the transistor','thay thế transistor')],'Each stage’s bias is isolated from the next.','Phân cực mỗi tầng được cách ly với tầng sau.','blocks\\s+the\\s+DC\\s+bias')
mcq('cpl',51,'Impedance coupling uses','Ghép trở kháng dùng',Y('a coil as the load of the first stage','cuộn cảm làm tải của tầng thứ nhất'),[Y('a capacitor only','chỉ tụ điện'),Y('a transformer with two secondaries','biến áp có hai thứ cấp'),Y('a wire link','dây nối trực tiếp')],'The coil’s impedance is high at high frequency, so it works best there.','Trở kháng cuộn cảm cao ở tần số cao nên hiệu quả nhất ở đó.','Impedance\\s+coupling\\s+uses\\s+a\\s+coil')
mcq('cpl',52,'A transformer-coupled stage can aid greatly with','Tầng ghép biến áp giúp nhiều cho',Y('impedance matching between stages','phối hợp trở kháng giữa các tầng'),[Y('removing all distortion','loại bỏ hết méo'),Y('raising the supply voltage','tăng điện áp nguồn'),Y('measuring temperature','đo nhiệt độ')],'It is described as very efficient.','Được mô tả là rất hiệu quả.','impedance\\s+matching\\s+between\\s+stages')
mcq('pp',52,'Power amplifiers are designed to','Bộ khuếch đại công suất được thiết kế để',Y('obtain a large amount of power with the fewest transistors and low distortion','tạo công suất lớn với ít transistor nhất và méo thấp'),[Y('obtain the highest voltage gain at any cost','đạt độ lợi điện áp cao nhất bằng mọi giá'),Y('amplify only dc signals','chỉ khuếch đại tín hiệu một chiều'),Y('replace the load with a resistor','thay tải bằng điện trở')],'Examples of loads: loudspeakers and servomotors in flight control.','Ví dụ tải: loa và động cơ servo trong điều khiển bay.','fewest\\s+transistors')
mcq('pp',52,'In a push-pull amplifier the transistors','Trong bộ khuếch đại đẩy kéo, các transistor',Y('carry the load peaks alternately','gánh các đỉnh tải luân phiên'),[Y('conduct together at all times and share equally','dẫn đồng thời mọi lúc và chia đều'),Y('both turn off at the signal peaks','cùng tắt ở các đỉnh tín hiệu'),Y('only amplify the positive half','chỉ khuếch đại nửa dương')],'When one conducts the other is off; the output transformer combines the halves.','Khi một transistor dẫn thì transistor kia tắt; biến áp ra ghép hai nửa.','alternately')
mcq('pp',52,'A push-pull amplifier is a classic example of a','Bộ khuếch đại đẩy kéo là ví dụ điển hình của',Y('class B amplifier','bộ khuếch đại lớp B'),[Y('class A amplifier','bộ khuếch đại lớp A'),Y('class C amplifier','bộ khuếch đại lớp C'),Y('class D switching regulator','ổn áp xung lớp D')],'Each transistor conducts for 50 % of the input.','Mỗi transistor dẫn 50 % tín hiệu vào.','classic\\s+example\\s+of\\s+a\\s+Class\\s+B')
