import re as _re
def add(tp, qen, qvi, ans, wr, xe, xv, lvl=2):
    ws = []
    for w in wr:
        if w != ans and w not in ws: ws.append(w)
    k = 3
    while len(ws) < 3:                      # pad with scaled copies of the answer (same unit)
        m = _re.search(r'-?[\d,]*\.?\d+', ans); v = float(m[0].replace(',', '')) * k; k += 4
        c = ans[:m.start()] + (f'{v:.3g}') + ans[m.end():]
        if c != ans and c not in ws: ws.append(c)
    wr = ws[:3]
    items.append(dict(kind='mcq', q=B(qen, qvi), opts=O([ans] + wr), correct=0, explain=B(xe, xv), level=lvl, topic=TT[tp], src=B('Generated – cascade/feedback formulas (Floyd Ch.6, 7, 12)', 'Bổ sung – công thức ghép tầng/hồi tiếp (Floyd Ch.6, 7, 12)'), origin='bo_sung', fixed_order=False, check='script'))
