for duty, vce, ic in [(0.10, 0.18, 25), (0.2, 0.2, 40), (0.05, 0.15, 100)]:
    p = duty * vce * ic * 1e-3 * 1e3
    add('cls', f'A class C transistor is on for {duty*100:.0f} % of the cycle with Vce(sat) = {vce} V and Ic(sat) = {ic} mA. What is the average power dissipation?', f'Transistor lớp C dẫn {duty*100:.0f} % chu kỳ với Vce(sat) = {vce} V và Ic(sat) = {ic} mA. Công suất tiêu tán trung bình là bao nhiêu?', f'{p:.3g} mW', [f'{vce*ic:.3g} mW', f'{p*10:.3g} mW', f'{p/10:.3g} mW', f'{duty*ic:.3g} mW'], f'PD = duty × Vce(sat) × Ic(sat) = {duty} × {vce} V × {ic} mA = {p:.3g} mW.', f'PD = chu kỳ × Vce(sat) × Ic(sat) = {duty} × {vce} V × {ic} mA = {p:.3g} mW.', 2)
